"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50313"],{5298(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_destinos","status":422,"titulo":"A cascata excede o limite de 56 destinos"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_destinos","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["A lista `destinos` do corpo do pedido de defini\xe7\xe3o da cascata tem mais de 56\\nposi\xe7\xf5es ao todo \u2014 a soma de todas as filas de todas as origens, n\xe3o s\xf3\\nde uma. Com o limite de 8 origens\\n([`excede_limite_de_origens`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_origens)),\\n56 \xe9 o teto de uma matriz completa com 7 destinos por origem \u2014 folga\\nsuficiente para qualquer cascata real sem abrir espa\xe7o para um corpo do pedido\\nanormalmente grande.","Pode coexistir, na mesma resposta, com\\n[`fallback_obrigatorio`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.fallback_obrigatorio),\\ncom `excede_limite_de_origens` e, quando algum item da lista \xe9 inv\xe1lido,\\ncom as causas de item \u2014 ver\\n[`campos_obrigatorios`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.campos_obrigatorios).\\nQuando todos os itens s\xe3o v\xe1lidos, pode coexistir tamb\xe9m com\\n[`ordem_duplicada_na_origem`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_duplicada_na_origem),\\n[`ordem_nao_contigua`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_nao_contigua)\\ne\\n[`destino_duplicado`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.destino_duplicado).\\nNunca coexiste com\\n[`sem_destinos`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.sem_destinos)\\n\u2014 exceder um limite exige destinos declarados."],"comoResolver":["Reduza o total de posi\xe7\xf5es declaradas em `destinos` para no m\xe1ximo 56,\\nsomando todas as origens. Revise se alguma origem tem destinos repetidos\\nou desnecess\xe1rios antes de considerar a cascata incompleta."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);